/* spells5.js — 141 уникальных заклинаний, написанных вручную (hand:true). */
(function(){const A=[{"id": "sp5-iskra-ozhidaniya", "n": "Искра ожидания", "l": 0, "sc": "Воплощение", "t": "1 действие", "r": "Касание", "c": "ВС", "m": "", "d": "1 минута", "conc": false, "rit": false, "dmg": "1к8 электричество", "save": "", "atk": false, "cl": ["Чародей", "Волшебник", "Изобретатель"], "ds": "Вы оставляете на предмете или участке пола размером 1,5 м невидимую искру. Первое существо, которое коснётся его, получает 1к8 урона электричеством, и искра гаснет. Одновременно может существовать только одна искра. Урон растёт на 1к8 на 5, 11 и 17 уровнях.", "higher": "Урон растёт на 1к8 на 5, 11 и 17 уровнях.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-shepot-sleda", "n": "Шёпот следа", "l": 0, "sc": "Прорицание", "t": "1 действие", "r": "На себя", "c": "ВС", "m": "", "d": "1 минута", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид", "Жрец"], "ds": "Вы касаетесь земли и узнаёте, сколько существ прошло по этому месту за последний час, их примерный размер и было ли среди них раненое. Вы получаете преимущество на следующую проверку Мудрости (Выживание) для выслеживания в течение действия.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-klyatvennyy-otblesk", "n": "Клятвенный отблеск", "l": 0, "sc": "Ограждение", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "1 раунд", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Жрец"], "ds": "Ваше оружие или щит вспыхивает. До начала вашего следующего хода, когда существо в пределах 1,5 м от вас попадает по союзнику атакой, вы можете реакцией уменьшить урон на 1к4 + ваш модификатор Харизмы. Уменьшение растёт на 1к4 на 5, 11 и 17 уровнях.", "higher": "Уменьшение растёт на 1к4 на 5, 11 и 17 уровнях.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-krovavyy-vsplesk", "n": "Кровавый всплеск", "l": 0, "sc": "Некромантия", "t": "1 действие", "r": "9 м", "c": "С", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "1к10 некротический", "save": "", "atk": true, "cl": ["Чародей", "Колдун"], "ds": "Вы выплёскиваете каплю собственной крови сгустком тьмы. Совершите дальнобойную атаку заклинанием: 1к10 некротического урона. Если вы сейчас имеете не больше половины хитов, бросок атаки совершается с преимуществом. Урон растёт на 1к10 на 5, 11 и 17 уровнях.", "higher": "Урон растёт на 1к10 на 5, 11 и 17 уровнях.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pylnyy-vihr", "n": "Пыльный вихрь", "l": 0, "sc": "Преобразование", "t": "1 действие", "r": "9 м", "c": "ВС", "m": "", "d": "1 раунд", "conc": false, "rit": false, "dmg": "", "save": "Телосложение", "atk": false, "cl": ["Друид", "Чародей", "Изобретатель"], "ds": "Вокруг существа взвивается пыль. Оно совершает спасбросок Телосложения или до конца своего следующего хода не видит дальше 3 м и не может совершать атаки по возможности.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-zvenyaschaya-struna", "n": "Звенящая струна", "l": 0, "sc": "Очарование", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "1к6 звук", "save": "Мудрость", "atk": false, "cl": ["Бард"], "ds": "Вы извлекаете резкую ноту. Цель совершает спасбросок Мудрости: при провале 1к6 урона звуком, и следующую проверку характеристики до конца своего следующего хода она совершает с помехой. Урон растёт на 1к6 на 5, 11 и 17 уровнях.", "higher": "Урон растёт на 1к6 на 5, 11 и 17 уровнях.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-ladon-ochaga", "n": "Ладонь очага", "l": 0, "sc": "Преобразование", "t": "1 действие", "r": "Касание", "c": "С", "m": "", "d": "8 часов", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид", "Жрец"], "ds": "Существо, которого вы касаетесь, перестаёт страдать от естественного холода до −30 °C. Если оно стабилизировано, но имеет 0 хитов, оно приходит в сознание с 1 хитом через 1к4 часа вместо 1к4 × 1к4.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-cheshuychatyy-pokrov", "n": "Чешуйчатый покров", "l": 0, "sc": "Преобразование", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "1 минута", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей"], "ds": "Вашу кожу покрывает тонкая чешуя ваших предков. Если вы не носите доспехов, ваш КД равен 12 + модификатор Ловкости. Заклинание оканчивается, если вы надеваете доспех. На 11 уровне КД равен 13 + модификатор Ловкости.", "higher": "На 11 уровне КД равен 13 + модификатор Ловкости.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-kolyuchiy-hlyst-lozy", "n": "Колючий хлыст лозы", "l": 0, "sc": "Преобразование", "t": "1 действие", "r": "4,5 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "1к6 колющий", "save": "", "atk": true, "cl": ["Друид"], "ds": "Из вашей руки вырастает лоза. Совершите рукопашную атаку заклинанием по существу в пределах 4,5 м: 1к6 колющего урона. Если цель Большая или меньше, вы можете подтянуть её на 3 м к себе или оттолкнуть на 3 м. Урон растёт на 1к6 на 5, 11 и 17 уровнях.", "higher": "Урон растёт на 1к6 на 5, 11 и 17 уровнях.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-glinyanaya-pechat", "n": "Глиняная печать", "l": 0, "sc": "Ограждение", "t": "1 действие", "r": "Касание", "c": "ВС", "m": "комок глины", "d": "24 часа", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Волшебник", "Изобретатель", "Жрец"], "ds": "Вы запечатываете дверь, сундук или свиток глиняной печатью с вашим знаком. Если печать сломают, вы чувствуете это, где бы ни находились на том же плане. Печать не мешает открыть предмет.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-lozhnyy-shag", "n": "Ложный шаг", "l": 0, "sc": "Иллюзия", "t": "1 действие", "r": "На себя", "c": "С", "m": "", "d": "1 раунд", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Бард", "Колдун", "Чародей"], "ds": "Ваш силуэт раздваивается. Первая атака по вам до начала вашего следующего хода совершается с помехой; если она промахивается, вы можете переместиться на 1,5 м, не провоцируя атак.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-ukus-moroza", "n": "Укус мороза", "l": 0, "sc": "Воплощение", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "1к6 холод", "save": "Телосложение", "atk": false, "cl": ["Чародей", "Волшебник", "Друид", "Изобретатель"], "ds": "Жгучий холод обжигает кончики пальцев существа. Спасбросок Телосложения: при провале 1к6 урона холодом, и первая атака оружием, которую цель совершит до конца своего следующего хода, наносит на 1к4 меньше урона. Урон растёт на 1к6 на 5, 11 и 17 уровнях.", "higher": "Урон растёт на 1к6 на 5, 11 и 17 уровнях.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-golos-svyaschennogo-kolokola", "n": "Голос священного колокола", "l": 0, "sc": "Воплощение", "t": "1 действие", "r": "На себя (радиус 3 м)", "c": "В", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "1к4 излучение", "save": "Мудрость", "atk": false, "cl": ["Жрец"], "ds": "Звучит удар колокола. Каждое враждебное существо в радиусе 3 м совершает спасбросок Мудрости или получает 1к4 урона излучением. Нежить и исчадия совершают спасбросок с помехой. Урон растёт на 1к4 на 5, 11 и 17 уровнях.", "higher": "Урон растёт на 1к4 на 5, 11 и 17 уровнях.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-lovchaya-metka", "n": "Ловчая метка", "l": 0, "sc": "Прорицание", "t": "1 бонусное действие", "r": "27 м", "c": "В", "m": "", "d": "1 минута", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид"], "ds": "Вы мысленно отмечаете существо, которое видите. Пока заклинание действует, первая ваша атака оружием по нему в каждый ваш ход наносит дополнительно 1 урон, и вы знаете, где оно, если оно в пределах 9 м, даже невидимое. Дополнительный урон растёт до 1к4 на 5 уровне, 1к6 на 11 и 1к8 на 17.", "higher": "Дополнительный урон растёт до 1к4 на 5 уровне, 1к6 на 11 и 1к8 на 17.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-uzel-vetra", "n": "Узел ветра", "l": 0, "sc": "Преобразование", "t": "1 действие", "r": "Касание", "c": "ВС", "m": "кусок верёвки", "d": "1 час", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид", "Чародей"], "ds": "Вы завязываете на верёвке узел, в который заключён порыв ветра. Развязав его действием, любое существо создаёт поток воздуха: лодка проходит 3 м, небольшой огонь гаснет, а летающее Крошечное существо отбрасывается на 4,5 м.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-mayatnik-udachi", "n": "Маятник удачи", "l": 0, "sc": "Прорицание", "t": "1 реакция (вы совершаете проверку характеристики)", "r": "На себя", "c": "С", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Бард", "Чародей", "Колдун"], "ds": "Вы бросаете к4 и прибавляете или вычитаете результат из своей проверки — решение принимается до объявления исхода. Затем до конца продолжительного отдыха ваш следующий спасбросок совершается с −1.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-znak-metkosti", "n": "Знак меткости", "l": 1, "sc": "Прорицание", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Изобретатель"], "ds": "Ваши глаза вспыхивают. Пока заклинание действует, ваши дальнобойные атаки оружием игнорируют укрытие на половину и на три четверти, а дистанция дальнего выстрела не накладывает помеху. На больших уровнях: На 3 уровне ячейки также +1к4 урона по существам, которые вы видели целиком хотя бы ход назад.", "higher": "На 3 уровне ячейки также +1к4 урона по существам, которые вы видели целиком хотя бы ход назад.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-ranyaschaya-otdacha", "n": "Ранящая отдача", "l": 1, "sc": "Ограждение", "t": "1 реакция (вас ранит рукопашная атака)", "r": "На себя", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "2к8 силовое поле", "save": "", "atk": false, "cl": ["Чародей", "Колдун", "Паладин"], "ds": "Ваша кожа отражает удар. Урон от атаки уменьшается вдвое, а атакующий получает 2к8 урона силовым полем. На больших уровнях: +1к8 к отражённому урону за уровень ячейки выше 1-го.", "higher": "+1к8 к отражённому урону за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-plamennaya-metka-drakona", "n": "Пламенная метка дракона", "l": 1, "sc": "Воплощение", "t": "1 бонусное действие", "r": "18 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "1к6 огонь", "save": "", "atk": false, "cl": ["Чародей"], "ds": "Вы отмечаете существо драконьим огнём. Каждый раз, когда вы попадаете по нему заклинанием, наносящим урон, оно получает дополнительно 1к6 урона огнём. Если цель умирает, бонусным действием перенесите метку на другую. На больших уровнях: +1к6 за каждые два уровня ячейки выше 1-го.", "higher": "+1к6 за каждые два уровня ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-beg-gonchey", "n": "Бег гончей", "l": 1, "sc": "Преобразование", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "1 минута", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Друид", "Паладин"], "ds": "Ваша скорость увеличивается на 3 м, и вы можете совершать действие Рывок бонусным действием. Движение по пересечённой местности не требует дополнительной скорости, если местность природная.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-obet-zaschitnika", "n": "Обет защитника", "l": 1, "sc": "Ограждение", "t": "1 бонусное действие", "r": "9 м", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин", "Жрец"], "ds": "Вы связываете себя с союзником. Пока он в пределах 9 м от вас, получив урон, он может перенести половину на вас; вы получаете этот урон, и его нельзя уменьшить. Кроме того, у союзника +1 к КД. На больших уровнях: Дополнительная цель за каждый уровень ячейки выше 1-го.", "higher": "Дополнительная цель за каждый уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-shipy-pod-nogami", "n": "Шипы под ногами", "l": 1, "sc": "Вызов", "t": "1 действие", "r": "18 м", "c": "ВСМ", "m": "горсть репейника", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "1к4 колющий", "save": "", "atk": false, "cl": ["Следопыт", "Друид", "Изобретатель"], "ds": "Квадрат со стороной 4,5 м покрывается магическими колючками. Это пересечённая местность. Существо, перемещающееся по нему, получает 1к4 колющего урона за каждые 1,5 м. Существо, которое знает о колючках, может идти со скоростью вдвое меньше и не получать урон. На больших уровнях: Сторона квадрата увеличивается на 3 м за уровень ячейки выше 1-го.", "higher": "Сторона квадрата увеличивается на 3 м за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-puls-haosa", "n": "Пульс хаоса", "l": 1, "sc": "Воплощение", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "2к8 случайный", "save": "Ловкость", "atk": false, "cl": ["Чародей"], "ds": "Сгусток дикой магии ударяет в точку. Каждое существо в радиусе 1,5 м совершает спасбросок Ловкости, при провале получая 2к8 урона (вдвое меньше при успехе). Тип урона определите к6: 1 кислота, 2 холод, 3 огонь, 4 электричество, 5 звук, 6 яд. Если на костях урона выпал дубль, бросьте снова за второй взрыв в другой точке в пределах 9 м. На больших уровнях: +1к8 за уровень ячейки выше 1-го.", "higher": "+1к8 за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-myagkaya-zemlya", "n": "Мягкая земля", "l": 1, "sc": "Преобразование", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "1 час", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид", "Следопыт", "Изобретатель"], "ds": "Почва в кубе с ребром 3 м становится рыхлой, как свежевспаханная. Любое существо падает на неё без урона от падения с высоты до 9 м; копать здесь можно в десять раз быстрее; следы на ней остаются чёткими.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-kleymo-trusosti", "n": "Клеймо трусости", "l": 1, "sc": "Очарование", "t": "1 действие", "r": "9 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Паладин", "Колдун", "Бард"], "ds": "Цель совершает спасбросок Мудрости. При провале, пока заклинание действует, каждый раз, когда она начинает ход в пределах 1,5 м от вас, она должна переместиться от вас хотя бы на 3 м, прежде чем атаковать. Она может повторять спасбросок в конце каждого своего хода. На больших уровнях: Дополнительная цель за каждый уровень ячейки выше 1-го.", "higher": "Дополнительная цель за каждый уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-lunnyy-serp", "n": "Лунный серп", "l": 1, "sc": "Воплощение", "t": "1 действие", "r": "На себя (линия 9 м)", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "2к6 излучение", "save": "Ловкость", "atk": false, "cl": ["Друид", "Чародей"], "ds": "Вы проводите рукой дугу, и вперёд летит серп бледного света длиной 9 м и шириной 1,5 м. Каждое существо на линии совершает спасбросок Ловкости, получая 2к6 урона излучением при провале или вдвое меньше при успехе. Перевертни совершают спасбросок с помехой. На больших уровнях: +1к6 за уровень ячейки выше 1-го.", "higher": "+1к6 за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-prival-bez-ognya", "n": "Привал без огня", "l": 1, "sc": "Ограждение", "t": "10 минут", "r": "На себя (радиус 6 м)", "c": "ВСМ", "m": "щепоть пепла", "d": "8 часов", "conc": false, "rit": true, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Друид"], "ds": "Лагерь в радиусе 6 м становится незаметен: дым и запахи не выходят наружу, звуки слышны лишь на 3 м, а внутри поддерживается тёплая температура без костра. Проверки Мудрости (Внимательность) снаружи для обнаружения лагеря совершаются с помехой.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-zhguchaya-sleza", "n": "Жгучая слеза", "l": 1, "sc": "Преобразование", "t": "1 действие", "r": "Касание", "c": "ВС", "m": "", "d": "1 минута", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Волшебник"], "ds": "Вы касаетесь оружия или боеприпаса. Следующее попадание им покрывает цель кислотой: 2к4 урона кислотой сразу и 2к4 в начале следующего хода цели, если она не потратит действие на то, чтобы стереть кислоту. На больших уровнях: +1к4 к обоим урону за уровень ячейки выше 1-го.", "higher": "+1к4 к обоим урону за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-udar-smireniya", "n": "Удар смирения", "l": 1, "sc": "Воплощение", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Паладин"], "ds": "В следующий раз, когда вы попадаете рукопашной атакой оружием, цель совершает спасбросок Мудрости. При провале она не может совершать реакции и бонусные действия до конца своего следующего хода и с помехой совершает следующую атаку не по вам.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pesnya-privala", "n": "Песня привала", "l": 1, "sc": "Очарование", "t": "1 минута", "r": "9 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Бард", "Следопыт", "Паладин"], "ds": "Вы напеваете дорожную песню. До шести существ, слышащих вас и проводящих короткий отдых, восстанавливают дополнительно 1к6 хитов, если тратят хотя бы одну Кость Хитов. На больших уровнях: Бонус растёт на 1к6 за уровень ячейки выше 1-го.", "higher": "Бонус растёт на 1к6 за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pelena-predchuvstviya", "n": "Пелена предчувствия", "l": 1, "sc": "Прорицание", "t": "1 реакция (вас атакуют, а вы не видите атакующего)", "r": "На себя", "c": "С", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Волшебник", "Чародей", "Колдун"], "ds": "Холодок по спине предупреждает вас. Атака по вам не получает преимущества за счёт того, что вы её не видите, и вы узнаёте направление, откуда она пришла.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-set-pautiny-duha", "n": "Сеть паутины духа", "l": 1, "sc": "Вызов", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Сила", "atk": false, "cl": ["Колдун", "Волшебник"], "ds": "Призрачная паутина опутывает Большое или меньшее существо. Оно совершает спасбросок Силы или становится опутанным. Опутанное существо может действием повторить спасбросок; при успехе заклинание оканчивается. Огонь разрывает сеть мгновенно. На больших уровнях: Дополнительная цель за каждый уровень ячейки выше 1-го.", "higher": "Дополнительная цель за каждый уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-hrustalnaya-strela", "n": "Хрустальная стрела", "l": 1, "sc": "Воплощение", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "1к10 колющий", "save": "", "atk": true, "cl": ["Чародей", "Следопыт", "Изобретатель"], "ds": "Вы выпускаете стрелу из прозрачного кристалла. Совершите дальнобойную атаку заклинанием: 1к10 колющего урона. При попадании стрела разлетается осколками, и каждое другое существо в пределах 1,5 м от цели получает 1к4 колющего урона. На больших уровнях: +1к10 за уровень ячейки выше 1-го.", "higher": "+1к10 за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-ladanka-strannika", "n": "Ладанка странника", "l": 1, "sc": "Ограждение", "t": "1 минута", "r": "Касание", "c": "ВСМ", "m": "мешочек с травами", "d": "24 часа", "conc": false, "rit": true, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Жрец", "Друид"], "ds": "Вы вешаете ладанку на шею существа. Пока заклинание действует, оно совершает с преимуществом спасброски от истощения из-за марша, жары и холода и может обходиться без воды вдвое дольше обычного. На больших уровнях: Дополнительная цель за каждый уровень ячейки выше 1-го.", "higher": "Дополнительная цель за каждый уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-opalyayuschaya-klyatva", "n": "Опаляющая клятва", "l": 1, "sc": "Воплощение", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "1к6 огонь", "save": "", "atk": false, "cl": ["Паладин"], "ds": "Ваш клинок раскаляется. Ваши рукопашные атаки оружием наносят дополнительно 1к6 урона огнём, а если вы доводите существо до 0 хитов, вы получаете временные хиты, равные вашему модификатору Харизмы. На больших уровнях: +1к6 за каждые два уровня ячейки выше 1-го.", "higher": "+1к6 за каждые два уровня ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-chuzhie-ruki", "n": "Чужие руки", "l": 1, "sc": "Очарование", "t": "1 действие", "r": "9 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Бард", "Чародей", "Колдун"], "ds": "Гуманоид совершает спасбросок Мудрости. При провале в начале каждого своего хода он совершает одно действие Использование предмета или Взаимодействие по вашему выбору (открыть дверь, бросить кошель, выпить зелье), если это не причиняет ему прямого вреда. Повтор спасброска в конце каждого хода.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-moros-vosstanovleniya", "n": "Морось восстановления", "l": 1, "sc": "Воплощение", "t": "1 действие", "r": "18 м", "c": "ВСМ", "m": "капля росы", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид", "Жрец"], "ds": "Тёплый дождь проливается в цилиндре радиусом 3 м. До пяти выбранных существ в нём восстанавливают по 1к4 хитов и могут закончить одно состояние «отравленный». На больших уровнях: +1к4 за уровень ячейки выше 1-го.", "higher": "+1к4 за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-slovo-otstupa", "n": "Слово отступа", "l": 1, "sc": "Вызов", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Колдун", "Волшебник"], "ds": "Вы телепортируетесь на 4,5 м в видимое свободное пространство. Если вы находились в пределах 1,5 м от врага, ваша следующая атака заклинанием по нему в этот ход совершается с преимуществом. На больших уровнях: Дистанция растёт на 3 м за уровень ячейки выше 1-го.", "higher": "Дистанция растёт на 3 м за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-voy-stai", "n": "Вой стаи", "l": 1, "sc": "Очарование", "t": "1 действие", "r": "На себя (радиус 9 м)", "c": "В", "m": "", "d": "1 раунд", "conc": false, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Следопыт", "Друид"], "ds": "Вы испускаете волчий вой. Враги в радиусе 9 м, слышащие вас, совершают спасбросок Мудрости или до конца вашего следующего хода атаки ваших союзников по ним совершаются с преимуществом, если рядом с целью стоит хотя бы ещё один союзник.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-legkiy-shag-piligrima", "n": "Лёгкий шаг пилигрима", "l": 1, "sc": "Преобразование", "t": "1 действие", "r": "Касание", "c": "ВС", "m": "", "d": "8 часов", "conc": false, "rit": true, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Паладин", "Жрец", "Друид"], "ds": "До трёх существ, которых вы касаетесь, проходят за день на 8 км больше обычного без риска истощения и не оставляют следов на траве и снегу. На больших уровнях: Дополнительная цель за каждый уровень ячейки выше 1-го.", "higher": "Дополнительная цель за каждый уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-gromovoy-hlopok-ladoney", "n": "Громовой хлопок ладоней", "l": 1, "sc": "Воплощение", "t": "1 действие", "r": "На себя (конус 4,5 м)", "c": "В", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "2к6 звук", "save": "Сила", "atk": false, "cl": ["Чародей", "Бард", "Волшебник"], "ds": "Вы хлопаете в ладоши. Каждое существо в конусе совершает спасбросок Силы: при провале 2к6 урона звуком и сбито с ног; при успехе половина урона. На больших уровнях: +1к6 за уровень ячейки выше 1-го.", "higher": "+1к6 за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-znak-tihoy-ohoty", "n": "Знак тихой охоты", "l": 1, "sc": "Иллюзия", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "Концентрация, до 10 минут", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт"], "ds": "Ваши шаги и дыхание становятся беззвучными, а запах исчезает. Вы получаете преимущество на проверки Ловкости (Скрытность), а звери не могут выследить вас по запаху. Если вы атакуете, заклинание оканчивается после атаки.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pokayanie", "n": "Покаяние", "l": 1, "sc": "Некромантия", "t": "1 действие", "r": "9 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "3к6 некротический", "save": "Харизма", "atk": false, "cl": ["Паладин", "Жрец"], "ds": "Вы указываете на существо, причинившее вред вашему союзнику за последнюю минуту. Оно совершает спасбросок Харизмы, получая 3к6 некротического урона при провале или вдвое меньше при успехе. Союзник восстанавливает хиты, равные половине нанесённого урона. На больших уровнях: +1к6 за уровень ячейки выше 1-го.", "higher": "+1к6 за уровень ячейки выше 1-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pepel-predkov", "n": "Пепел предков", "l": 1, "sc": "Прорицание", "t": "1 минута", "r": "На себя", "c": "ВСМ", "m": "пепел очага", "d": "Мгновенная", "conc": false, "rit": true, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Жрец"], "ds": "Вы бросаете пепел в огонь и задаёте вопрос о текущем месте. Дым складывается в образ того, что происходило здесь самым значимым за последние 10 лет, — сцену длиной не более одного вздоха.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-chary-slomannogo-klinka", "n": "Чары сломанного клинка", "l": 1, "sc": "Преобразование", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "Сила", "atk": false, "cl": ["Чародей", "Волшебник", "Изобретатель"], "ds": "Немагическое оружие в руках существа покрывается трещинами. Владелец совершает спасбросок Силы: при провале до конца его следующего хода оружие наносит урон с помехой (бросайте урон дважды и выбирайте меньший).", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-cep-molniy-po-klinkam", "n": "Цепь молний по клинкам", "l": 2, "sc": "Воплощение", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "2к8 электричество", "save": "Ловкость", "atk": false, "cl": ["Чародей", "Волшебник", "Изобретатель"], "ds": "Молния бьёт в существо, носящее металлическое оружие или доспех, затем перескакивает на ещё одно такое существо в пределах 6 м от первого, и ещё на одно. Каждая цель совершает спасбросок Ловкости: 2к8 урона электричеством при провале, вдвое меньше при успехе. Существа без металла цепь пропускает. На больших уровнях: +1 прыжок за уровень ячейки выше 2-го.", "higher": "+1 прыжок за уровень ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-ohotnichiy-kapkan-duha", "n": "Охотничий капкан духа", "l": 2, "sc": "Вызов", "t": "1 минута", "r": "Касание", "c": "ВСМ", "m": "зуб волка", "d": "8 часов", "conc": false, "rit": false, "dmg": "3к6 силовое поле", "save": "Сила", "atk": false, "cl": ["Следопыт", "Друид"], "ds": "Вы прячете в квадрате 1,5 м призрачный капкан. Первое существо, вошедшее туда, совершает спасбросок Силы: при провале 3к6 урона силовым полем и становится схваченным капканом (СЛ побега = ваша СЛ заклинаний) на 1 минуту; при успехе половина урона. Найти капкан можно проверкой Мудрости (Внимательность) против вашей СЛ. На больших уровнях: +1к6 за уровень ячейки выше 2-го.", "higher": "+1к6 за уровень ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-svyataya-opora", "n": "Святая опора", "l": 2, "sc": "Ограждение", "t": "1 бонусное действие", "r": "На себя (радиус 3 м)", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин"], "ds": "Пока вы стоите на месте, вас окружает сияние радиусом 3 м. Союзники в нём не могут быть сбиты с ног или сдвинуты против их воли и получают +2 к спасброскам Силы. Если вы перемещаетесь, заклинание оканчивается. На больших уровнях: Радиус растёт на 1,5 м за уровень ячейки выше 2-го.", "higher": "Радиус растёт на 1,5 м за уровень ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-zybkaya-kozha", "n": "Зыбкая кожа", "l": 2, "sc": "Преобразование", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Волшебник"], "ds": "Ваше тело становится текучим. Вы можете проходить через щели шириной 2,5 см, совершаете с преимуществом проверки на побег из захвата и оков, а критические попадания по вам становятся обычными.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-peschanye-chasy-vraga", "n": "Песчаные часы врага", "l": 2, "sc": "Преобразование", "t": "1 действие", "r": "18 м", "c": "ВСМ", "m": "песчинка", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Чародей", "Колдун", "Волшебник"], "ds": "Существо совершает спасбросок Мудрости. При провале в каждый свой ход оно может совершить либо действие, либо перемещение, но не оба, и не может совершать реакции. Повтор спасброска в конце каждого его хода. На больших уровнях: Дополнительная цель за каждый уровень ячейки выше 2-го.", "higher": "Дополнительная цель за каждый уровень ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-dymnaya-zavesa-sledopyta", "n": "Дымная завеса следопыта", "l": 2, "sc": "Вызов", "t": "1 бонусное действие", "r": "18 м", "c": "ВСМ", "m": "щепоть сажи", "d": "1 минута", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Изобретатель"], "ds": "Вы бросаете шарик, и в сфере радиусом 3 м поднимается густой дым — местность сильно заслонена. В отличие от обычного тумана вы и выбранные вами существа видят сквозь дым на 3 м. Сильный ветер рассеивает его за 1 раунд.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-krov-drakona-probuzhdaetsya", "n": "Кровь дракона пробуждается", "l": 2, "sc": "Преобразование", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей"], "ds": "Вы получаете сопротивление урону того типа, что соответствует вашему наследию (или огню), а один раз в ход, нанося такой урон заклинанием, прибавляете к нему свой модификатор Харизмы. У вас появляются призрачные крылья: скорость полёта 6 м, но вы падаете в конце хода, если не на опоре.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-vyazkiy-vzglyad", "n": "Вязкий взгляд", "l": 2, "sc": "Очарование", "t": "1 действие", "r": "9 м", "c": "С", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Бард", "Колдун", "Чародей"], "ds": "Существо, видящее вас, совершает спасбросок Мудрости. При провале его скорость равна 0, пока оно видит вас и вы не делаете ничего, кроме поддержания концентрации и разговора. Если вы атакуете или двигаетесь, заклинание оканчивается.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-shag-skvoz-hvoyu", "n": "Шаг сквозь хвою", "l": 2, "sc": "Ограждение", "t": "1 действие", "r": "На себя (радиус 9 м)", "c": "ВСМ", "m": "ветка ели", "d": "1 час", "conc": false, "rit": true, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Друид"], "ds": "До десяти выбранных существ в радиусе 9 м получают +10 к проверкам Ловкости (Скрытность) в природной местности и не оставляют следов. Атака или громкий шум оканчивает эффект для этого существа.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-nastupatelnyy-obet", "n": "Наступательный обет", "l": 2, "sc": "Очарование", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "1к8 излучение", "save": "", "atk": false, "cl": ["Паладин"], "ds": "Выберите видимого врага. Пока заклинание действует, ваши атаки по нему наносят дополнительно 1к8 урона излучением, а он совершает с помехой атаки по существам, кроме вас. Если вы атакуете кого-то другого, заклинание оканчивается. На больших уровнях: +1к8 за каждые два уровня ячейки выше 2-го.", "higher": "+1к8 за каждые два уровня ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-rezhuschiy-veter", "n": "Режущий ветер", "l": 2, "sc": "Воплощение", "t": "1 действие", "r": "На себя (линия 18 м)", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "3к8 рубящий", "save": "Ловкость", "atk": false, "cl": ["Друид", "Чародей"], "ds": "Лезвие ветра проносится по линии 18 м шириной 1,5 м. Каждое существо в ней совершает спасбросок Ловкости, получая 3к8 рубящего урона при провале или вдвое меньше при успехе. Незакреплённые лёгкие предметы на линии отлетают на 3 м. На больших уровнях: +1к8 за уровень ячейки выше 2-го.", "higher": "+1к8 за уровень ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-glaza-yastreba", "n": "Глаза ястреба", "l": 2, "sc": "Прорицание", "t": "1 действие", "r": "Касание", "c": "ВСМ", "m": "перо", "d": "1 час", "conc": false, "rit": true, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Друид", "Изобретатель"], "ds": "Существо, которого вы касаетесь, видит на 1,5 км так же чётко, как на 30 м, может различить мелкие детали на этом расстоянии и совершает с преимуществом проверки Мудрости (Внимательность), полагающиеся на зрение.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-poserebrennaya-plot", "n": "Посеребрённая плоть", "l": 2, "sc": "Преобразование", "t": "1 действие", "r": "Касание", "c": "ВСМ", "m": "серебряная монета", "d": "1 час", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин", "Жрец", "Следопыт"], "ds": "Кожа существа отливает серебром. Его безоружные удары и атаки оружием считаются посеребрёнными, а перевертни и исчадия, кусающие его, получают 1к6 урона излучением.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-otrazhenie-vspyat", "n": "Отражение вспять", "l": 2, "sc": "Ограждение", "t": "1 реакция (вас поражает заклинание с броском атаки)", "r": "На себя", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Волшебник"], "ds": "Совершите проверку характеристики заклинаний; СЛ = 10 + уровень заклинания. При успехе атака промахивается, а вы можете совершить той же атакой дальнобойную атаку заклинанием по её создателю, используя свой бонус. На больших уровнях: Бонус +1 к проверке за уровень ячейки выше 2-го.", "higher": "Бонус +1 к проверке за уровень ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-slezy-zemli", "n": "Слёзы земли", "l": 2, "sc": "Вызов", "t": "1 действие", "r": "36 м", "c": "ВСМ", "m": "капля смолы", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Сила", "atk": false, "cl": ["Друид", "Изобретатель"], "ds": "Из земли в квадрате 6 м сочится вязкая смола. Это пересечённая местность. Существо, начинающее ход в ней, совершает спасбросок Силы или становится опутанным до начала следующего хода. Смола легко воспламеняется: огонь наносит 2к6 урона огнём всем внутри и уничтожает её.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-vspyshka-sokola", "n": "Вспышка сокола", "l": 2, "sc": "Преобразование", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "1 раунд", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Чародей"], "ds": "До конца хода ваша скорость удваивается, вы можете пролететь это расстояние, и атаки по вам совершаются с помехой. В конце хода вы мягко опускаетесь на землю.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-holodnaya-yarost-klyatvy", "n": "Холодная ярость клятвы", "l": 2, "sc": "Ограждение", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин"], "ds": "Вы получаете сопротивление дробящему, колющему и рубящему урону, но не можете совершать атаки по существам, которые не атаковали вас или ваших союзников с момента наложения заклинания.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-oskolki-sna", "n": "Осколки сна", "l": 2, "sc": "Очарование", "t": "1 действие", "r": "27 м", "c": "ВСМ", "m": "лепесток мака", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Бард", "Чародей", "Волшебник"], "ds": "В сфере радиусом 3 м рассыпаются сверкающие осколки. Каждое существо в ней совершает спасбросок Мудрости. При провале оно теряет следующую реакцию и до конца своего хода совершает проверки и спасброски Ловкости с помехой. Существо с не более чем 20 хитами при провале засыпает на 1 минуту. На больших уровнях: Порог хитов растёт на 10 за уровень ячейки выше 2-го.", "higher": "Порог хитов растёт на 10 за уровень ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-proklyatie-hromoty", "n": "Проклятие хромоты", "l": 2, "sc": "Некромантия", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Телосложение", "atk": false, "cl": ["Колдун", "Жрец", "Волшебник"], "ds": "Существо совершает спасбросок Телосложения. При провале его скорость уменьшается вдвое, и оно не может совершать Рывок. Каждый раз, когда оно получает урон некротической энергией, скорость падает ещё на 3 м. Повтор спасброска в конце каждого хода.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-zharyaschee-solnce", "n": "Жарящее солнце", "l": 2, "sc": "Воплощение", "t": "1 действие", "r": "36 м", "c": "ВСМ", "m": "линза", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "2к6 огонь", "save": "", "atk": false, "cl": ["Друид", "Чародей"], "ds": "Луч сфокусированного солнечного света падает на квадрат 1,5 м. Существо, начинающее там ход или входящее туда, получает 2к6 урона огнём. Бонусным действием вы смещаете луч на 6 м. Луч работает только под открытым небом днём. На больших уровнях: +1к6 за уровень ячейки выше 2-го.", "higher": "+1к6 за уровень ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-svyazka-strel", "n": "Связка стрел", "l": 2, "sc": "Преобразование", "t": "1 бонусное действие", "r": "Касание", "c": "ВС", "m": "", "d": "1 минута", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Изобретатель"], "ds": "Вы касаетесь до 10 стрел или болтов. Каждый раз, когда вы попадаете таким боеприпасом, следующая стрела из связки возвращается в ваш колчан, если дальность не больше 36 м. Такие боеприпасы не ломаются.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-skrezhet-kamnya", "n": "Скрежет камня", "l": 2, "sc": "Преобразование", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "3к6 дробящий", "save": "Телосложение", "atk": false, "cl": ["Друид", "Волшебник", "Изобретатель"], "ds": "Камень, металл или кость в пределах дистанции содрогается. Существо из такого вещества (голем, нежить-скелет, элементаль земли) или в каменной броне совершает спасбросок Телосложения: 3к6 дробящего урона при провале, половина при успехе. Предметы получают максимальный урон. На больших уровнях: +1к6 за уровень ячейки выше 2-го.", "higher": "+1к6 за уровень ячейки выше 2-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-znamya-voinstva", "n": "Знамя воинства", "l": 3, "sc": "Вызов", "t": "1 действие", "r": "На себя (радиус 9 м)", "c": "ВСМ", "m": "лоскут знамени", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин", "Жрец"], "ds": "Над вами вспыхивает призрачное знамя. Союзники в радиусе 9 м добавляют к4 к спасброскам, а один раз в ход, попадая по врагу, могут восстановить 1к4 хитов. Бонусным действием вы переносите знамя в пространство в пределах 9 м. На больших уровнях: Радиус растёт на 3 м за уровень ячейки выше 3-го.", "higher": "Радиус растёт на 3 м за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-staya-voron", "n": "Стая ворон", "l": 3, "sc": "Вызов", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "3к6 колющий", "save": "Ловкость", "atk": false, "cl": ["Колдун", "Друид", "Следопыт"], "ds": "В кубе с ребром 6 м кружат призрачные вороны. Местность там слабо заслонена; существо, начинающее ход внутри, совершает спасбросок Ловкости: 3к6 колющего урона при провале, половина при успехе. Бонусным действием вы перемещаете стаю на 9 м. На больших уровнях: +1к6 за уровень ячейки выше 3-го.", "higher": "+1к6 за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-razryv-barerov", "n": "Разрыв барьеров", "l": 3, "sc": "Ограждение", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Волшебник", "Колдун"], "ds": "Все заклинания ограждения 3 уровня или ниже в кубе с ребром 6 м оканчиваются. Для каждого заклинания выше 3 уровня совершите проверку характеристики заклинаний СЛ 10 + его уровень. Магические двери и замки в зоне открываются. На больших уровнях: Порог автоматического снятия растёт на 1 за уровень ячейки выше 3-го.", "higher": "Порог автоматического снятия растёт на 1 за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-volna-metamorfoza", "n": "Волна метаморфоза", "l": 3, "sc": "Преобразование", "t": "1 действие", "r": "На себя", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей"], "ds": "Вы выбираете две из следующих черт и можете менять одну на другую бонусным действием: когти (1к8 рубящий, атака заклинанием); жабры и скорость плавания 12 м; паучьи лапы (лазание по потолку); кожа камня (+2 КД); крылья (полёт 9 м). На больших уровнях: Дополнительная черта на 5 уровне ячейки.", "higher": "Дополнительная черта на 5 уровне ячейки.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-neotvratimaya-strela", "n": "Неотвратимая стрела", "l": 3, "sc": "Прорицание", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "1 раунд", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт"], "ds": "Ваша следующая дальнобойная атака оружием в этот ход не может промахнуться из-за укрытия, невидимости или магии отражения, если цель в пределах дистанции; бросьте атаку как обычно — при промахе она всё равно попадает, но наносит половину урона.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-svyaschennaya-kara-vozmezdiya", "n": "Священная кара возмездия", "l": 3, "sc": "Воплощение", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "3к8 излучение", "save": "", "atk": false, "cl": ["Паладин"], "ds": "Следующая рукопашная атака оружием, которая попадает по существу, недавно ранившему вашего союзника, наносит дополнительно 3к8 урона излучением, а цель светится тусклым светом и не может стать невидимой 1 минуту. На больших уровнях: +1к8 за уровень ячейки выше 3-го.", "higher": "+1к8 за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pepelnyy-grad", "n": "Пепельный град", "l": 3, "sc": "Воплощение", "t": "1 действие", "r": "45 м", "c": "ВСМ", "m": "горсть пепла", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "4к6 огонь", "save": "Ловкость", "atk": false, "cl": ["Чародей", "Волшебник", "Друид"], "ds": "С неба в цилиндре радиусом 6 м падают раскалённые угли. Каждое существо внутри совершает спасбросок Ловкости, получая 4к6 урона огнём при провале или половину при успехе. Зона остаётся пересечённой местностью до конца вашего следующего хода, и в ней тлеет пепел. На больших уровнях: +1к6 за уровень ячейки выше 3-го.", "higher": "+1к6 за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-lozhnoe-telo", "n": "Ложное тело", "l": 3, "sc": "Иллюзия", "t": "1 реакция (вы получаете урон от атаки)", "r": "На себя", "c": "С", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Бард", "Чародей", "Изобретатель"], "ds": "Атака поражает иллюзорного двойника. Вы не получаете урона и становитесь невидимым до начала своего следующего хода, а двойник падает «замертво» и исчезает через 1 минуту. Существо, коснувшееся тела, понимает обман.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-zverinyy-soyuz", "n": "Звериный союз", "l": 3, "sc": "Очарование", "t": "1 минута", "r": "9 м", "c": "ВСМ", "m": "лакомство для зверя", "d": "24 часа", "conc": false, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Следопыт", "Друид"], "ds": "Зверь с Интеллектом 3 или ниже совершает спасбросок Мудрости (с преимуществом, если враждебен). При провале он становится вашим спутником на время действия: понимает простые команды, действует в вашу инициативу и защищает вас, но не идёт на очевидную смерть. На больших уровнях: Опасность зверя растёт: ПО 2 на 3 уровне, +1 ПО за каждый уровень ячейки выше.", "higher": "Опасность зверя растёт: ПО 2 на 3 уровне, +1 ПО за каждый уровень ячейки выше.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-kamennyy-son", "n": "Каменный сон", "l": 3, "sc": "Преобразование", "t": "1 действие", "r": "18 м", "c": "ВСМ", "m": "кусочек гранита", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Телосложение", "atk": false, "cl": ["Волшебник", "Чародей", "Друид"], "ds": "Существо совершает спасбросок Телосложения. При провале его ноги каменеют: скорость 0, ловкость в спасбросках с помехой. В конце каждого его хода повтор: три провала — существо окаменевает целиком на 1 час, три успеха — заклинание оканчивается.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-golos-povelitelya", "n": "Голос повелителя", "l": 3, "sc": "Очарование", "t": "1 действие", "r": "18 м", "c": "В", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Чародей", "Бард", "Паладин"], "ds": "Вы произносите одно слово-приказ, и до трёх существ совершают спасбросок Мудрости. При провале каждое в свой следующий ход выполняет приказ: «Ниц», «Беги», «Брось», «Стой» или «Ко мне». Приказ, ведущий к прямому вреду, не выполняется. На больших уровнях: Дополнительная цель за уровень ячейки выше 3-го.", "higher": "Дополнительная цель за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-reka-dush", "n": "Река душ", "l": 3, "sc": "Некромантия", "t": "1 действие", "r": "На себя (линия 18 м)", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "5к6 некротический", "save": "Телосложение", "atk": false, "cl": ["Колдун", "Волшебник"], "ds": "Поток прозрачных лиц проносится по линии 18 м шириной 3 м. Каждое существо в ней совершает спасбросок Телосложения, получая 5к6 некротического урона при провале или половину при успехе. Вы получаете временные хиты, равные числу существ, проваливших спасбросок, умноженному на 3. На больших уровнях: +1к6 за уровень ячейки выше 3-го.", "higher": "+1к6 за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-siyayuschiy-prolet", "n": "Сияющий пролёт", "l": 3, "sc": "Вызов", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 часа", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Жрец", "Паладин", "Волшебник"], "ds": "Вы создаёте мост из твёрдого света шириной 1,5 м и длиной до 36 м между двумя видимыми точками. Мост выдерживает любой вес, тускло светится и не может быть разрушен обычными средствами; рассеивание магии разрушает его. На больших уровнях: Длина растёт на 18 м за уровень ячейки выше 3-го.", "higher": "Длина растёт на 18 м за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-vozvraschenie-klinka", "n": "Возвращение клинка", "l": 3, "sc": "Вызов", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "1 час", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин", "Следопыт", "Изобретатель"], "ds": "Вы связываете с собой оружие, которое держите. Бонусным действием вы призываете его в руку из любой точки в пределах 1,5 км. Если его держит другое существо, оно совершает спасбросок Силы, чтобы удержать его.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-okovy-sveta", "n": "Оковы света", "l": 3, "sc": "Ограждение", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Харизма", "atk": false, "cl": ["Паладин", "Жрец"], "ds": "Цепи из света опутывают существо. Исчадие, нежить или фея совершает спасбросок Харизмы: при провале оно опутано и не может телепортироваться или покидать план. Другие существа совершают спасбросок с преимуществом. Повтор в конце каждого хода. На больших уровнях: Дополнительная цель за уровень ячейки выше 3-го.", "higher": "Дополнительная цель за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-burevaya-strela", "n": "Буревая стрела", "l": 3, "sc": "Воплощение", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "1 раунд", "conc": false, "rit": false, "dmg": "4к8 электричество", "save": "Ловкость", "atk": false, "cl": ["Следопыт", "Чародей"], "ds": "Следующая ваша дальнобойная атака оружием в этот ход превращается в молнию. Независимо от попадания по цели, линия от вас до неё становится разрядом: каждое существо на линии совершает спасбросок Ловкости, получая 4к8 урона электричеством при провале или половину при успехе. На больших уровнях: +1к8 за уровень ячейки выше 3-го.", "higher": "+1к8 за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-chuzhoy-son", "n": "Чужой сон", "l": 3, "sc": "Очарование", "t": "1 минута", "r": "Особая", "c": "ВСМ", "m": "прядь волос цели", "d": "8 часов", "conc": false, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Бард", "Колдун", "Чародей"], "ds": "Вы проникаете в сон спящего существа на том же плане. Вы можете вести беседу; если цель провалит спасбросок Мудрости, она проснётся с чувством, что сон был правдивым, и будет склонна выполнить одно ваше разумное пожелание в течение дня.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-udar-lednika", "n": "Удар ледника", "l": 3, "sc": "Воплощение", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "6к6 холод", "save": "Сила", "atk": false, "cl": ["Чародей", "Волшебник", "Друид"], "ds": "На существо обрушивается глыба льда. Спасбросок Силы: при провале 6к6 урона холодом и цель сбита с ног и опутана льдом до конца своего следующего хода; при успехе половина урона. Глыба остаётся как препятствие 1,5 м и тает за 1 минуту. На больших уровнях: +1к6 за уровень ячейки выше 3-го.", "higher": "+1к6 за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-nekolebimaya-vera", "n": "Неколебимая вера", "l": 3, "sc": "Ограждение", "t": "1 действие", "r": "9 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Жрец", "Паладин"], "ds": "До трёх существ не могут быть очарованы или испуганы. Если существо уже очаровано или испугано, это состояние подавляется. Каждое из них получает 2к6 временных хитов. На больших уровнях: Дополнительная цель за уровень ячейки выше 3-го.", "higher": "Дополнительная цель за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-vzglyad-cherez-plamya", "n": "Взгляд через пламя", "l": 3, "sc": "Прорицание", "t": "1 действие", "r": "Особая", "c": "ВСМ", "m": "горстка соли", "d": "Концентрация, до 10 минут", "conc": true, "rit": true, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Волшебник", "Колдун", "Жрец"], "ds": "Вы смотрите в огонь и видите сквозь любой другой открытый огонь размером с факел или больше, который видели раньше, на том же плане. Вы слышите звуки рядом с ним. Бонусным действием вы переключаетесь на другой знакомый огонь.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-zemlyanoy-hvat", "n": "Земляной хват", "l": 3, "sc": "Преобразование", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "2к6 дробящий", "save": "Сила", "atk": false, "cl": ["Друид", "Следопыт"], "ds": "Земля вокруг существа смыкается. Спасбросок Силы: при провале оно схвачено и опутано, получая 2к6 дробящего урона в начале каждого своего хода. Действием цель повторяет спасбросок. Летающие и плывущие не подвержены. На больших уровнях: +1к6 за уровень ячейки выше 3-го.", "higher": "+1к6 за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-plamennyy-vihr-charodeya", "n": "Пламенный вихрь чародея", "l": 3, "sc": "Воплощение", "t": "1 действие", "r": "На себя (радиус 3 м)", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "3к6 огонь", "save": "Ловкость", "atk": false, "cl": ["Чародей"], "ds": "Вас окружает кольцо огня радиусом 3 м, движущееся вместе с вами. Враг, впервые за ход входящий в кольцо или начинающий в нём ход, совершает спасбросок Ловкости, получая 3к6 урона огнём при провале или половину при успехе. На больших уровнях: +1к6 за уровень ячейки выше 3-го.", "higher": "+1к6 за уровень ячейки выше 3-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-sokrytie-otryada", "n": "Сокрытие отряда", "l": 3, "sc": "Иллюзия", "t": "1 действие", "r": "На себя (радиус 9 м)", "c": "ВСМ", "m": "кусочек коры", "d": "1 час", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Изобретатель", "Волшебник"], "ds": "До шести существ в радиусе 9 м приобретают окраску окружения: пока они не двигаются быстрее половины скорости, проверки Мудрости (Внимательность) для их обнаружения совершаются с помехой, а они сами получают +5 к Скрытности.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-krovavyy-obet-mesti", "n": "Кровавый обет мести", "l": 4, "sc": "Некромантия", "t": "1 бонусное действие", "r": "18 м", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "2к8 некротический", "save": "", "atk": false, "cl": ["Паладин", "Колдун"], "ds": "Вы клянётесь отомстить существу, которое только что опустило союзника до 0 хитов или ранило его. Ваши атаки по нему наносят дополнительно 2к8 некротического урона, вы знаете его местоположение в пределах 1,5 км, а оно не может восстанавливать хиты, пока заклинание действует. На больших уровнях: +1к8 за каждые два уровня ячейки выше 4-го.", "higher": "+1к8 за каждые два уровня ячейки выше 4-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-burya-perev", "n": "Буря перьев", "l": 4, "sc": "Вызов", "t": "1 действие", "r": "36 м", "c": "ВСМ", "m": "перо орла", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Сила", "atk": false, "cl": ["Друид", "Следопыт", "Чародей"], "ds": "В цилиндре радиусом 6 м и высотой 12 м бушует вихрь перьев. Местность сильно заслонена для всех, кроме вас. Существо, начинающее ход внутри, совершает спасбросок Силы или поднимается на 6 м и падает в конце хода, получая урон от падения.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-zerkalnaya-kozha", "n": "Зеркальная кожа", "l": 4, "sc": "Ограждение", "t": "1 действие", "r": "На себя", "c": "ВСМ", "m": "осколок зеркала", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Волшебник"], "ds": "Ваша кожа становится зеркальной. Первый раз в каждый раунд, когда вас атакует заклинание или вы проваливаете спасбросок от заклинания, бросьте к6: на 4–6 эффект отражается на создателя (он совершает спасбросок или по нему совершается атака с теми же параметрами).", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-tropa-hischnika", "n": "Тропа хищника", "l": 4, "sc": "Преобразование", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт"], "ds": "Вы сливаетесь с природой. Вы не провоцируете атак при перемещении, ваша скорость +6 м, а когда вы атакуете существо, которое не видело вас в начале хода, атака наносит дополнительно 3к6 урона того же типа.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-lovushka-prostranstva", "n": "Ловушка пространства", "l": 4, "sc": "Ограждение", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Харизма", "atk": false, "cl": ["Волшебник", "Чародей", "Колдун"], "ds": "Существо совершает спасбросок Харизмы. При провале оно не может телепортироваться, перемещаться между планами или становиться эфирным, а каждый раз, перемещаясь более чем на 3 м за ход, получает 2к10 урона силовым полем. Повтор в конце каждого хода.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-grad-meteoritov-charodeya", "n": "Град метеоритов чародея", "l": 4, "sc": "Воплощение", "t": "1 действие", "r": "45 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "3к10 огонь", "save": "Ловкость", "atk": false, "cl": ["Чародей"], "ds": "Три огненных камня падают в три точки на расстоянии не менее 6 м друг от друга. Каждое существо в радиусе 3 м от точки совершает спасбросок Ловкости, получая 3к10 урона огнём (половину при успехе). Существо, задетое двумя взрывами, получает урон только один раз, но совершает спасбросок с помехой. На больших уровнях: +1 камень за уровень ячейки выше 4-го.", "higher": "+1 камень за уровень ячейки выше 4-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-posoh-zemli", "n": "Посох земли", "l": 4, "sc": "Преобразование", "t": "1 бонусное действие", "r": "На себя", "c": "ВСМ", "m": "дубовый жёлудь", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид", "Следопыт"], "ds": "Ваш посох или копьё пускает корни. Пока вы стоите на земле, вы не можете быть сбиты с ног, а атаки им наносят дополнительно 1к8 дробящего урона и опутывают Большую или меньшую цель до начала вашего следующего хода (спасбросок Силы отменяет опутывание).", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-svet-posledney-nadezhdy", "n": "Свет последней надежды", "l": 4, "sc": "Воплощение", "t": "1 действие", "r": "На себя (радиус 9 м)", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин", "Жрец"], "ds": "Каждый союзник в радиусе 9 м, у которого 0 хитов, восстанавливает 2к8 + ваш модификатор заклинаний хитов и может немедленно встать без затраты перемещения. Существо может извлечь пользу из этого заклинания раз в день. На больших уровнях: +1к8 за уровень ячейки выше 4-го.", "higher": "+1к8 за уровень ячейки выше 4-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-plenenie-teni", "n": "Пленение тени", "l": 4, "sc": "Некромантия", "t": "1 действие", "r": "18 м", "c": "ВСМ", "m": "чёрная нить", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Колдун", "Волшебник"], "ds": "Вы пронзаете тень существа. Оно совершает спасбросок Мудрости: при провале его скорость 0, а вы можете бонусным действием заставить тень ударить его (2к8 некротического урона). Яркий свет со всех сторон уничтожает связь.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-klyatva-nerushimogo-stroya", "n": "Клятва нерушимого строя", "l": 4, "sc": "Ограждение", "t": "1 действие", "r": "На себя (радиус 3 м)", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин"], "ds": "Союзники в радиусе 3 м от вас получают +2 к КД, а когда враг попадает по одному из них, вы можете реакцией переместиться на 3 м к атакованному и стать целью атаки вместо него.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pesn-otrazhennyh-golosov", "n": "Песнь отражённых голосов", "l": 4, "sc": "Иллюзия", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Интеллект", "atk": false, "cl": ["Бард", "Чародей"], "ds": "До четырёх существ слышат голоса своих союзников, отдающие ложные приказы. Каждое совершает спасбросок Интеллекта; при провале в начале своего хода оно бросает к4: на 1–2 перемещается к ближайшему союзнику и атакует его, на 3–4 действует нормально. Повтор в конце хода.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-shkval-klinkov-vetra", "n": "Шквал клинков ветра", "l": 4, "sc": "Воплощение", "t": "1 действие", "r": "На себя (радиус 4,5 м)", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "5к8 рубящий", "save": "Ловкость", "atk": false, "cl": ["Чародей", "Друид", "Следопыт"], "ds": "Вокруг вас разворачивается вихрь режущего ветра. Каждое существо в радиусе 4,5 м совершает спасбросок Ловкости, получая 5к8 рубящего урона при провале или половину при успехе. После этого вы можете взлететь на 6 м без провоцирования атак. На больших уровнях: +1к8 за уровень ячейки выше 4-го.", "higher": "+1к8 за уровень ячейки выше 4-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-chertog-otdyha", "n": "Чертог отдыха", "l": 4, "sc": "Вызов", "t": "10 минут", "r": "9 м", "c": "ВСМ", "m": "ключ", "d": "8 часов", "conc": false, "rit": true, "dmg": "", "save": "", "atk": false, "cl": ["Волшебник", "Изобретатель", "Бард"], "ds": "Вы открываете дверь в карманный покой 6 × 6 м с очагом, кроватями и чистой водой. Внутри могут находиться до восьми существ; вход виден только им. Продолжительный отдых там восстанавливает дополнительно одну Кость Хитов.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-chernaya-zvezda", "n": "Чёрная звезда", "l": 4, "sc": "Воплощение", "t": "1 действие", "r": "45 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "2к10 силовое поле", "save": "Сила", "atk": false, "cl": ["Волшебник", "Чародей", "Колдун"], "ds": "В точке появляется сфера гравитации радиусом 6 м. Существа, начинающие ход внутри, совершают спасбросок Силы: при провале притягиваются на 3 м к центру и получают 2к10 урона силовым полем. Местность внутри пересечённая. На больших уровнях: +1к10 за каждые два уровня ячейки выше 4-го.", "higher": "+1к10 за каждые два уровня ячейки выше 4-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-skakun-rassveta", "n": "Скакун рассвета", "l": 4, "sc": "Вызов", "t": "1 минута", "r": "9 м", "c": "ВС", "m": "", "d": "8 часов", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин"], "ds": "Вы призываете сияющего коня (КД 14, хиты 40, скорость 18 м, полёт 18 м). Пока вы верхом, вы получаете сопротивление некротическому урону, а ваши атаки с разбега (6 м по прямой) наносят дополнительно 2к8 урона излучением. На больших уровнях: Хиты коня +10 за уровень ячейки выше 4-го.", "higher": "Хиты коня +10 за уровень ячейки выше 4-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-razdelennaya-suschnost", "n": "Разделённая сущность", "l": 4, "sc": "Преобразование", "t": "1 действие", "r": "На себя", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Колдун"], "ds": "Вы расщепляетесь на два тела в пределах 9 м друг от друга. У вас общие хиты и действия, но каждое тело может стать источником заклинаний и атак. Бонусным действием вы меняете тела местами. Если одно тело получает урон, второе — нет.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pylca-bespamyatstva", "n": "Пыльца беспамятства", "l": 4, "sc": "Очарование", "t": "1 действие", "r": "18 м", "c": "ВСМ", "m": "цветок лотоса", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Друид", "Бард"], "ds": "В сфере радиусом 6 м рассыпается золотая пыльца. Каждое существо совершает спасбросок Мудрости: при провале оно забывает последние 10 минут и в течение следующего раунда не понимает, что происходит (не может совершать реакции, проверки Интеллекта и Мудрости с помехой).", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-kupol-klyatvy", "n": "Купол клятвы", "l": 5, "sc": "Ограждение", "t": "1 действие", "r": "На себя (радиус 4,5 м)", "c": "ВСМ", "m": "святой символ", "d": "Концентрация, до 10 минут", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин", "Жрец"], "ds": "Вас окружает непробиваемый для заклинаний 3 уровня и ниже купол. Враги не могут войти в него, если не преуспеют в спасброске Харизмы; существа внутри получают +1 к спасброскам. Вы и купол неподвижны. На больших уровнях: Порог заклинаний растёт на 1 за уровень ячейки выше 5-го.", "higher": "Порог заклинаний растёт на 1 за уровень ячейки выше 5-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-ohota-pod-lunoy", "n": "Охота под луной", "l": 5, "sc": "Прорицание", "t": "1 действие", "r": "На себя", "c": "ВСМ", "m": "клык", "d": "8 часов", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Следопыт", "Друид"], "ds": "Вы называете существо, которое видели или о котором имеете часть тела. Вы знаете направление к нему и расстояние, если оно на том же плане, и до конца действия ваши атаки по нему совершаются с преимуществом и наносят дополнительно 2к6 урона.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pylayuschaya-krov", "n": "Пылающая кровь", "l": 5, "sc": "Воплощение", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "3к6 огонь", "save": "", "atk": false, "cl": ["Чародей"], "ds": "Ваша кровь становится пламенем. Существо, попадающее по вам рукопашной атакой, получает 3к6 урона огнём. Вы получаете сопротивление огню и, получив урон, можете бонусным действием выпустить вспышку: 3к6 урона огнём каждому существу в пределах 3 м (спасбросок Ловкости вдвое). На больших уровнях: +1к6 за уровень ячейки выше 5-го.", "higher": "+1к6 за уровень ячейки выше 5-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-navazhdenie-labirinta", "n": "Наваждение лабиринта", "l": 5, "sc": "Иллюзия", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Интеллект", "atk": false, "cl": ["Волшебник", "Бард", "Изобретатель"], "ds": "Существо видит вокруг себя лабиринт стен. Спасбросок Интеллекта: при провале оно перемещается лишь на половину скорости в случайном направлении (к8) и считается ослеплённым ко всему, что дальше 3 м. Повтор в конце каждого хода; Интеллект 18+ даёт преимущество.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-sto-shagov-teni", "n": "Сто шагов тени", "l": 5, "sc": "Вызов", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Колдун", "Чародей", "Следопыт"], "ds": "Пока вы в тусклом свете или темноте, вы можете бонусным действием телепортироваться на 18 м в другую видимую точку тусклого света или темноты. Каждая атака после телепортации в тот же ход совершается с преимуществом.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-svod-kamnya", "n": "Свод камня", "l": 5, "sc": "Вызов", "t": "1 действие", "r": "36 м", "c": "ВСМ", "m": "галька", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид", "Волшебник", "Изобретатель"], "ds": "Вы создаёте из камня сооружение объёмом до 10 кубов с ребром 3 м: стены, лестницы, крыши и мосты. Каждая плита толщиной 15 см имеет КД 15 и 50 хитов. Сооружение постоянно. На больших уровнях: +5 кубов за уровень ячейки выше 5-го.", "higher": "+5 кубов за уровень ячейки выше 5-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-sud-nad-nepravednym", "n": "Суд над неправедным", "l": 5, "sc": "Воплощение", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "8к8 излучение", "save": "Харизма", "atk": false, "cl": ["Паладин", "Жрец"], "ds": "Вы называете преступление, в котором, по вашему знанию, виновно существо. Оно совершает спасбросок Харизмы, получая 8к8 урона излучением при провале или половину при успехе. Если оно невиновно, заклинание не наносит урона, а вы получаете 2к8 урона излучением. На больших уровнях: +1к8 за уровень ячейки выше 5-го.", "higher": "+1к8 за уровень ячейки выше 5-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-morskoy-zmey-voli", "n": "Морской змей воли", "l": 5, "sc": "Вызов", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Концентрация, до 10 минут", "conc": true, "rit": false, "dmg": "4к10 дробящий", "save": "Сила", "atk": false, "cl": ["Друид", "Чародей"], "ds": "Из водоёма поднимается змей из воды длиной 9 м. Бонусным действием он хлещет существо в пределах 9 м: спасбросок Силы, 4к10 дробящего урона и сбит с ног при провале. Змей может проглотить Среднее существо (опутано, 2к10 дробящего в начале хода).", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-svyazuyuschaya-pesn", "n": "Связующая песнь", "l": 5, "sc": "Очарование", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 часа", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Бард", "Жрец"], "ds": "До восьми союзников связаны мелодией. Пока они в пределах 1,5 км друг от друга, они могут общаться мысленно, чувствуют боль друг друга и один раз в ход могут передать союзнику свою реакцию.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-mercayuschaya-armiya", "n": "Мерцающая армия", "l": 5, "sc": "Иллюзия", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Бард", "Изобретатель", "Чародей"], "ds": "Вы создаёте иллюзию отряда из 20 воинов. Существа, видящие их, совершают спасбросок Мудрости или испуганы, пока видят армию. Бонусным действием вы заставляете отряд «атаковать» существо: оно совершает тот же спасбросок или получает 4к6 психического урона.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-zhar-gorna-predkov", "n": "Жар горна предков", "l": 5, "sc": "Преобразование", "t": "1 минута", "r": "Касание", "c": "ВСМ", "m": "угли из кузни", "d": "8 часов", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Паладин", "Изобретатель", "Жрец"], "ds": "Немагическое оружие или доспех, которого вы касаетесь, становится магическим: +2 к атаке и урону для оружия или +2 к КД для доспеха. Пока действует, предмет нельзя повредить немагическими средствами.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-ugasanie-magii", "n": "Угасание магии", "l": 6, "sc": "Ограждение", "t": "1 действие", "r": "36 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Телосложение", "atk": false, "cl": ["Волшебник", "Чародей"], "ds": "Существо совершает спасбросок Телосложения. При провале оно не может накладывать заклинания выше 2 уровня и не может концентрироваться. В начале каждого его хода, если оно пытается творить магию, оно получает 3к6 урона силовым полем.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-tysyacha-shipov", "n": "Тысяча шипов", "l": 6, "sc": "Вызов", "t": "1 действие", "r": "36 м", "c": "ВСМ", "m": "колючка ежевики", "d": "Концентрация, до 10 минут", "conc": true, "rit": false, "dmg": "6к8 колющий", "save": "Ловкость", "atk": false, "cl": ["Друид"], "ds": "В цилиндре радиусом 9 м вырастает живая ежевика. Существо, входящее в неё или начинающее ход внутри, совершает спасбросок Ловкости: 6к8 колющего урона при провале, половина при успехе. Местность сильно заслонена и пересечённая; вы и выбранные существа проходят свободно.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-spiralnyy-haos", "n": "Спиральный хаос", "l": 6, "sc": "Преобразование", "t": "1 действие", "r": "45 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "Харизма", "atk": false, "cl": ["Чародей"], "ds": "Каждое существо в сфере радиусом 6 м совершает спасбросок Харизмы. При провале бросьте к6: 1 — превращается в безобидного зверя на 1 минуту; 2 — телепортируется на 18 м; 3 — 10к6 силового урона; 4 — ослеплено и оглушено до конца хода; 5 — меняется местами с другой целью; 6 — ничего.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-klinok-posledney-klyatvy", "n": "Клинок последней клятвы", "l": 6, "sc": "Воплощение", "t": "1 бонусное действие", "r": "На себя", "c": "В", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "4к10 излучение", "save": "", "atk": false, "cl": ["Жрец"], "ds": "Ваше оружие превращается в клинок из света. Атаки им наносят дополнительно 4к10 урона излучением; если они доводят существо до 0 хитов, вы и союзники в пределах 9 м восстанавливаете по 2к10 хитов.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-staya-prizrachnyh-volkov", "n": "Стая призрачных волков", "l": 6, "sc": "Вызов", "t": "1 действие", "r": "36 м", "c": "ВСМ", "m": "волчий клык", "d": "Концентрация, до 1 часа", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид"], "ds": "Появляются шесть призрачных волков (КД 14, хиты 30, скорость 15 м, атака +8, 2к8 колющего, сбивает с ног). Они действуют в вашу инициативу и проходят сквозь препятствия, но не могут закончить в них ход.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-ognennaya-dusha-zemli", "n": "Огненная душа земли", "l": 6, "sc": "Воплощение", "t": "1 действие", "r": "45 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "10к6 огонь", "save": "Ловкость", "atk": false, "cl": ["Чародей", "Друид", "Волшебник"], "ds": "Земля в радиусе 9 м извергает лаву. Каждое существо совершает спасбросок Ловкости, получая 10к6 урона огнём при провале или половину при успехе. Область становится лавовым полем на 1 минуту: 2к10 урона огнём за каждые 1,5 м пути. На больших уровнях: +1к6 за уровень ячейки выше 6-го.", "higher": "+1к6 за уровень ячейки выше 6-го.", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-izgnanie-vo-sne", "n": "Изгнание во сне", "l": 6, "sc": "Очарование", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Мудрость", "atk": false, "cl": ["Бард", "Колдун", "Волшебник"], "ds": "Существо совершает спасбросок Мудрости. При провале его разум переносится во сон, а тело остаётся без сознания. В конце каждого его хода оно может повторить спасбросок. Урон даёт преимущество на повтор, а не будит сразу.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-karta-mirov", "n": "Карта миров", "l": 6, "sc": "Прорицание", "t": "10 минут", "r": "На себя", "c": "ВСМ", "m": "карта стоимостью 100 зм", "d": "Мгновенная", "conc": false, "rit": true, "dmg": "", "save": "", "atk": false, "cl": ["Волшебник", "Жрец"], "ds": "Вы раскладываете карту, и на ней проступают все порталы, двери между планами и места пересечения мира с другими планами в радиусе 150 км, а также — какие из них открыты.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-voinstvo-solnca", "n": "Воинство солнца", "l": 6, "sc": "Вызов", "t": "1 действие", "r": "36 м", "c": "ВСМ", "m": "золотая монета", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Жрец"], "ds": "Вы призываете трёх солнечных воинов (КД 18, хиты 50, атака +9, 2к8+5 рубящего + 2к6 излучение). Нежить в пределах 3 м от воина совершает спасброски с помехой.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-padenie-zvezdy", "n": "Падение звезды", "l": 7, "sc": "Воплощение", "t": "1 действие", "r": "150 м", "c": "ВСМ", "m": "метеоритное железо", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "12к10 огонь и дробящий", "save": "Ловкость", "atk": false, "cl": ["Чародей", "Волшебник", "Друид"], "ds": "В точку падает звезда. Существа в радиусе 9 м совершают спасбросок Ловкости, получая 6к10 урона огнём и 6к10 дробящего урона при провале или половину при успехе. Образуется кратер глубиной 3 м.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-perekovannaya-sudba", "n": "Перекованная судьба", "l": 7, "sc": "Прорицание", "t": "1 реакция (бросок в пределах 18 м)", "r": "18 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей", "Бард", "Колдун"], "ds": "Вы переписываете исход броска к20 любого существа: он считается выпавшим 20 или 1 по вашему выбору. После этого вы не можете совершать броски с преимуществом до конца продолжительного отдыха.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-lesnoe-bezmolvie", "n": "Лесное безмолвие", "l": 7, "sc": "Ограждение", "t": "1 действие", "r": "На себя (радиус 1,5 км)", "c": "ВСМ", "m": "сухой лист", "d": "24 часа", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид"], "ds": "Лес вокруг вас становится враждебен к чужакам: тропы путаются, звери предупреждают вас, и существа, которых вы не назвали, преодолевают вдвое меньшее расстояние и совершают проверки Выживания с помехой.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-prigovor-nebosvoda", "n": "Приговор небосвода", "l": 7, "sc": "Воплощение", "t": "1 действие", "r": "36 м", "c": "В", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "Харизма", "atk": false, "cl": ["Жрец"], "ds": "Вы призываете суд высших сил. Выбранное существо совершает спасбросок Харизмы; при провале оно получает 10к10 урона излучением, а исчадие или нежить с хитами 100 и ниже уничтожается. При успехе — половина урона.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-uzy-mirov", "n": "Узы миров", "l": 7, "sc": "Вызов", "t": "1 минута", "r": "Касание", "c": "ВСМ", "m": "два кольца", "d": "Пока не рассеется", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Волшебник", "Колдун", "Чародей"], "ds": "Вы связываете две двери на одном плане. Проход через одну выводит из другой. Связь можно сделать односторонней и защитить паролем.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-vihr-vechnosti", "n": "Вихрь вечности", "l": 7, "sc": "Преобразование", "t": "1 действие", "r": "18 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "Телосложение", "atk": false, "cl": ["Волшебник", "Чародей"], "ds": "Существо совершает спасбросок Телосложения. При провале оно стареет на 1к10 × 10 лет (бессмертные не подвержены) и получает одну степень истощения в конце каждого своего хода, пока не преуспеет в повторе.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pesn-sotvoreniya", "n": "Песнь сотворения", "l": 8, "sc": "Преобразование", "t": "1 минута", "r": "36 м", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Бард", "Друид", "Жрец"], "ds": "В радиусе 36 м мёртвая земля оживает: вырастают деревья и травы, источники очищаются, проклятия места 7 уровня и ниже снимаются. Все союзники восстанавливают 4к10 хитов.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-beskonechnaya-ohota", "n": "Бесконечная охота", "l": 8, "sc": "Прорицание", "t": "1 действие", "r": "Особая", "c": "ВСМ", "m": "кровь цели", "d": "Пока не рассеется", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Колдун"], "ds": "Вы связываете себя с существом. Вы всегда знаете его план, направление и расстояние; оно не может укрыться от вас прорицанием. Ваши атаки по нему всегда наносят критическое попадание при 19–20.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-korona-drakona", "n": "Корона дракона", "l": 8, "sc": "Преобразование", "t": "1 бонусное действие", "r": "На себя", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Чародей"], "ds": "Вы принимаете облик дракона: Огромный размер, КД 19, временные хиты 100, полёт 24 м, укус +12 (3к10+6). Раз в 1к6 раундов вы выдыхаете конус 18 м (12к6 урона вашим типом стихии, спасбросок Ловкости вдвое).", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-bastion-svyatogo-prestola", "n": "Бастион святого престола", "l": 8, "sc": "Ограждение", "t": "1 минута", "r": "На себя (радиус 18 м)", "c": "ВСМ", "m": "реликвия", "d": "24 часа", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Жрец"], "ds": "Область становится святым местом: исчадия, нежить и феи не могут войти без спасброска Харизмы (раз в день), союзники не могут быть очарованы или испуганы, а лечение внутри максимально.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-bezdonnaya-tma", "n": "Бездонная тьма", "l": 8, "sc": "Вызов", "t": "1 действие", "r": "45 м", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "6к10 холод", "save": "Мудрость", "atk": false, "cl": ["Колдун", "Волшебник"], "ds": "В сфере радиусом 9 м образуется тьма из Далёкого Края. Существо внутри получает 6к10 урона холодом в начале хода и совершает спасбросок Мудрости или безумно бежит в случайном направлении.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-rassvet-nad-peplom", "n": "Рассвет над пеплом", "l": 9, "sc": "Воплощение", "t": "1 действие", "r": "На себя (радиус 300 м)", "c": "ВС", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "20к10 излучение", "save": "Телосложение", "atk": false, "cl": ["Жрец", "Чародей"], "ds": "Вспыхивает свет солнца. Враждебные существа в радиусе 300 м совершают спасбросок Телосложения, получая 20к10 урона излучением при провале или половину при успехе; нежить и исчадия получают максимум. Союзники восстанавливают все хиты.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-pervozdannaya-yarost", "n": "Первозданная ярость", "l": 9, "sc": "Преобразование", "t": "1 действие", "r": "На себя", "c": "ВС", "m": "", "d": "Концентрация, до 1 минуты", "conc": true, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Друид", "Чародей"], "ds": "Вы становитесь воплощением стихии: размер Огромный, иммунитет к одному типу урона стихий, ваши атаки наносят 6к10 урона, а вы можете раз в ход вызвать бурю, землетрясение или пожар в радиусе 18 м (уровень эффекта 8).", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}, {"id": "sp5-otmena-mgnoveniya", "n": "Отмена мгновения", "l": 9, "sc": "Прорицание", "t": "1 реакция (в конце хода существа)", "r": "На себя", "c": "В", "m": "", "d": "Мгновенная", "conc": false, "rit": false, "dmg": "", "save": "", "atk": false, "cl": ["Волшебник", "Чародей", "Бард"], "ds": "Вы отменяете последний ход другого существа: всё, что оно сделало, отменяется, и оно не может повторить тот же выбор. Израсходованные ячейки и предметы возвращаются.", "higher": "", "orig": true, "hand": true, "pack": "spells5.js"}];const D=window.DATA=window.DATA||{};D.spells=D.spells||[];const ids=new Set(D.spells.map(s=>s.id));A.forEach(s=>{if(!ids.has(s.id))D.spells.push(s)});})();
